-- One slot. Draft only.
BEGIN;
-- PT114-S2-Q25
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND q.stimulus=$batch01$In our solar system only one of the nine planets—Earth—qualifies as fit to sustain life. Nonetheless, using this ratio, and considering the astonishingly large number of planetary systems in the universe, we must conclude that the number of planets fit to sustain some form of life is extremely large.$batch01$ AND q.prompt=$batch01$The argument is questionable because it presumes which one of the following without providing justification?$batch01$ AND q.correct_choice=$batch01$B$batch01$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$If a planet is Earthlike, then life will arise on it.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q25 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$Our solar system is similar to many other planetary systems in the universe.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q25 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$The conditions necessary for life to begin are well understood.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q25 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$Life similar to Earth’s could evolve under conditions very different from those on Earth.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q25 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$Most other planetary systems in the universe have nine planets.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q25 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT114-S2-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The universe contains an extremely large number of planets fit to sustain some form of life.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$One of the nine planets in our solar system qualifies, and the universe has astonishingly many planetary systems.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Multiplying one solar system's proportion by many systems assumes that our system resembles a great many others in the relevant respect. If most other systems contain no life-sustaining planets, a huge number of systems would not validate the projected ratio. The argument offers one observed system as a sample of the universe.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the assumption that our solar system is sufficiently typical of other planetary systems.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$A planet being fit to sustain life does not guarantee that life arises on it. The conclusion concerns *fitness*, not the actual origin of life.$batch01$), ($batch01$B$batch01$, $batch01$The argument extrapolates from our system's one-in-nine ratio to numerous other systems. That inference needs many other systems to be similar to ours in the prevalence of life-sustaining planets. Without that, the local ratio tells us little about the universe-wide count.$batch01$), ($batch01$C$batch01$, $batch01$We need not understand how life begins to assess the premise's stipulated judgment that Earth is fit to sustain it. The projection across systems is the gap.$batch01$), ($batch01$D$batch01$, $batch01$The argument does not require Earthlike life to evolve elsewhere, or require life to evolve at all. It counts planets capable of sustaining *some form* of life.$batch01$), ($batch01$E$batch01$, $batch01$Other systems need not have exactly nine planets. They need a comparable frequency of life-sustaining planets for the extrapolation to work. Nine is the denominator in our system, not a required size for every system.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT114-S2-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
